// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testFuzz_property(address nonOwner, address newOwner) public {
        vm.assume(nonOwner != address(this));
        vm.assume(newOwner != address(0));
        address initialOwner = c.owner();
        vm.prank(nonOwner);
        bool ok = true;
        try c.transferOwnership(newOwner) { } catch { ok = false; }
        assertTrue(!ok || c.owner() == initialOwner);
    }
}
